SELECT total_assets, net_profit_or_loss, bussiness_profit FROM Finance WHERE bussiness_profit != '470734000' AND registered_office != '225 NE Mizner Blvd, Suite 640, Boca Raton, FL 33432' AND largest_shareholder = 'The Master Trust Bank 
of Japan, Ltd. (Trust 
account)' AND net_profit_or_loss = '27299000';

WITH knicks_players AS (
    SELECT * FROM w WHERE "previous team" = 'new york knicks'
), not_used AS (
    SELECT * FROM w WHERE player = 'john barnhill'
) SELECT * FROM knicks_players WHERE "years of nba experience" > 1
AND {{
        LLMMap(
            'Did they play more than one position?',
            knicks_players.pos
        )
    }} = TRUE

SELECT title, player FROM w JOIN documents d ON{{
    LLMJoin(
        w.player,
        d.title
    )
}} WHERE {{
    LLMMap(
       'How many years with the franchise?',
       "career with the franchise"
    )
}} > 5

{{
    get_table_size(
        (
            WITH a AS (
                SELECT * FROM (SELECT DISTINCT * FROM portfolio) as w
                    WHERE {{test_starts_with('F', w.Symbol)}} = TRUE
            ) SELECT * FROM a WHERE LENGTH(a.Symbol) > 2
        )
    )
}}

SELECT w."Percent of Account" FROM (SELECT * FROM "portfolio" WHERE Quantity > 200 OR "Today''s Gain/Loss Percent" > 0.05) as w
JOIN geographic g ON {{
    do_join(
        w.Symbol,
        g.Symbol
    )
}} WHERE {{test_starts_with('F', w.Symbol)}}
AND w."Percent of Account" < 0.2

SELECT "Name",
{{ImageCaption(Image)}} as "Image Description",
{{
    LLMMap(
        question='Size in km2?',
        context=Area
    )
}} as "Size in km" FROM parks
WHERE "Location" = 'Alaska'
ORDER BY "Size in km" DESC LIMIT 1

SELECT "Name", "Description" FROM parks
WHERE {{
    LLMMap(
        'Does this location have park facilities?',
        Description
    )
}} = FALSE

SELECT "Location", "Name" AS "Park Protecting Ash Flow" FROM parks
WHERE "Name" = {{
  LLMQA(
    'Which park protects an ash flow?',
    context=(SELECT "Name", "Description" FROM parks),
    options=Name
  )
}}

SELECT * FROM w
    WHERE city = {{
        LLMQA(
            'Which city is located 120 miles west of Sydney?',
            (SELECT * FROM documents WHERE documents MATCH 'sydney OR 120'),
            options=city
        )
    }}

SELECT DISTINCT venue FROM w
    WHERE city = 'sydney' AND {{
        LLMMap(
            'More than 30 total points?',
            score
        )
    }} = TRUE

SELECT date, rival, score, d.content AS "Team Description" FROM w
    JOIN documents d ON {{
        LLMJoin(
            w.rival,
            d.title
        )
    }} WHERE rival = 'nsw waratahs'

SELECT rival
FROM w
WHERE city = {{
    LLMQA(
        'What city features the Mount Panorama racetrack?',
        (SELECT title, content FROM documents WHERE documents MATCH 'mount panorama racetrack')
    )
}}
